param([Parameter(Mandatory=$true)][string]$RunId)
$ErrorActionPreference='Stop'
# Local/background jobs use UUID hex; admitted platform turns use SHA-256.
# Keep command identities limited to the UUID form generated by Commands.
if($RunId -notmatch '^([0-9a-f]{32}|[0-9a-f]{64}|cmd-[0-9a-f]{32})$'){throw 'Execution identity required'}
$ancRoot=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$ancDirectory=Join-Path $ancRoot 'Control\DesktopHosts'
if($RunId.StartsWith('cmd-') -and (Test-Path -LiteralPath $ancDirectory)){[IO.File]::WriteAllText((Join-Path $ancDirectory ($RunId+'.stop')),'finished')}
foreach($ancName in @(('LOOM-Job-'+$RunId),('LOOM-Desktop-'+$RunId))){
    $ancDeadline=[DateTime]::UtcNow.AddSeconds(8)
    do {
        $ancTask=Get-ScheduledTask -TaskName $ancName -ErrorAction SilentlyContinue
        if(-not $ancTask -or $ancTask.State -ne 'Running'){break}
        Start-Sleep -Milliseconds 200
    } while([DateTime]::UtcNow -lt $ancDeadline)
    if($ancTask -and $ancTask.State -eq 'Running'){throw 'Execution task remains active; keep recovery pending'}
    if($ancTask){Unregister-ScheduledTask -TaskName $ancName -Confirm:$false}
}
$ancReceipt=Join-Path $ancDirectory ($RunId+'.json')
if(Test-Path -LiteralPath $ancReceipt){
    $ancResult=Get-Content -LiteralPath $ancReceipt -Raw | ConvertFrom-Json
    if($ancResult.id -ne $RunId -or -not $ancResult.desktop_closed -or -not $ancResult.station_closed){throw 'Desktop object cleanup not confirmed'}
}
